		// The palette getRawThemeColors returns for a futuristic theme, or null for every other theme.
		function fxPaletteFor(name) {
			const t = fxThemeFor(name);
			return t ? Object.assign({}, t.palette) : null;
		}

		function fxStyleEl(id) {
			let el = document.getElementById(id);
			if (!el) { el = document.createElement("style"); el.id = id; document.head.appendChild(el); }
			return el;
		}

		// Turns the effects layer on or off for the form canvas and the toolbar and tab chrome, following formSpec.theme and formSpec.fx_mode.
		// The code editor and the properties panel never get it: no blur behind code, no scanlines over text you edit.
		function applyFxToCanvas() {
			const canvas = document.getElementById("formCanvas");
			if (!canvas) return;
			const t = fxThemeFor(formSpec.theme);
			const mode = formSpec.fx_mode === "off" ? "off" : (formSpec.fx_mode === "reduced" ? "reduced" : "on");
			const sig = (t ? t.key : "") + "|" + mode;
			if (fxState.sig === sig) return;
			fxState.sig = sig;
			const live = !!t && mode !== "off";
			Array.prototype.slice.call(canvas.attributes).forEach(function (a) { if (a.name.indexOf("data-fx") === 0) canvas.removeAttribute(a.name); });
			canvas.classList.toggle("fx-root", live);
			if (live) {
				Object.keys(t.attrs).forEach(function (k) { canvas.setAttribute(k, t.attrs[k]); });
				canvas.setAttribute("data-fx", mode);
			}
			const chrome = [[".app-header", null], [".tab-bar", "fx-nav"], [".canvas-toolbar", "fx-toolbar"], [".toolbar-actions", "fx-toolbar"]];
			chrome.forEach(function (c) {
				document.querySelectorAll(c[0]).forEach(function (el) {
					if (live) el.setAttribute("data-fx", mode); else el.removeAttribute("data-fx");
					if (c[1]) el.classList.toggle(c[1], live);
				});
			});
			document.querySelectorAll(".app-header .btn").forEach(function (b) { b.classList.toggle("fx-button", live); });
			if (t) {
				fxStyleEl("fxDesignerVars").textContent = ":root { " + t.vars + " }";
				const css = fxStyleEl("fxDesignerCss");
				if (!css.textContent) css.textContent = FX_CSS_TEXT;
			} else {
				const vars = document.getElementById("fxDesignerVars");
				if (vars) vars.textContent = "";
			}
			if (live && !fxState.pointer) fxState.pointer = FX_POINTER_FN(window);
			if (!live && fxState.pointer) { fxState.pointer.dispose(); fxState.pointer = null; }
			if (fxState.pointer) fxState.pointer.refresh();
		}

		// Keeps the theme and effects selects in step with the form (after a restore, an import, an undo or a new form).
		function syncThemeControls() {
			const themeSel = document.getElementById("propFormTheme");
			if (themeSel && formSpec.theme && themeSel.value !== formSpec.theme) {
				for (let i = 0; i < themeSel.options.length; i++) {
					if (themeSel.options[i].value === formSpec.theme) { themeSel.value = formSpec.theme; break; }
				}
			}
			const fxSel = document.getElementById("propFormFx");
			const wanted = formSpec.fx_mode || "full";
			if (fxSel && fxSel.value !== wanted) fxSel.value = wanted;
			applyFxToCanvas();
		}

		function updateFxMode() {
			saveHistoryState();
			const sel = document.getElementById("propFormFx");
			formSpec.fx_mode = sel ? sel.value : "full";
			renderCanvas();
			syncSpecToV();
			document.getElementById("statusMsg").textContent = "Effects set to " + formSpec.fx_mode + ".";
		}
